(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[175],{1514:function(n,e,t){"use strict";t.r(e),e.default={code:"M1-08",title:"排序應用：連動資料處理",tier:"t1",unlockCode:"M1-08-SortApplied",tasks:[{id:"seclect-002",code:"M1-08-seclect-002",title:"卡片位置交換清單版",description:"小安已經學會「兩個變數的交換」，現在他拿到一排固定 5 張的數字卡片，\n卡片依序放在第 1 到第 5 個位置中。\n老師指定清單中的兩個位置，小安需要把這兩個位置上的數字卡片進行交換，\n其他位置的卡片保持不變。\n請你寫一個程式，完成指定「清單位址」的資料交換。\n（提示：交換時仍然需要使用暫存變數）",examples:[{input:"5\n8 3 5 1 6\n2\n2 4",output:"8 1 5 3 6",explanation:"第2個位置是 3，第4個位置是 1，\n交換後，其餘位置不變。"},{input:"5\n4 7 2 9 5\n2\n1 5",output:"5 7 2 9 4",explanation:"交換第1與第5個位置的卡片。"}],testCases:[{input:"5\n8 3 5 1 6\n2\n2 4",expectedOutput:"8 1 5 3 6",score:10},{input:"5\n4 7 2 9 5\n2\n1 5",expectedOutput:"5 7 2 9 4",score:10},{input:"5\n6 6 6 6 6\n2\n3 4",expectedOutput:"6 6 6 6 6",score:10},{input:"5\n1 2 3 4 5\n2\n2 3",expectedOutput:"1 3 2 4 5",score:10},{input:"5\n9 8 7 6 5\n2\n1 4",expectedOutput:"6 8 7 9 5",score:10}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/M1-08-SortApplied/seclect-002.sb3"},{id:"seclect-003",code:"M1-08-seclect-003",title:"清單最大最小值的位置",description:"在進行排序之前，程式必須先知道「最大值或最小值在清單的哪一個位置」。\n小安已經可以找出清單中的最大值與最小值，\n但老師希望他進一步找出該數值所在的位置（索引值），\n才能正確進行資料交換。\n現在給你一個固定長度為 5 的整數清單，\n請找出清單中最小值所在的位置。\n注意事項：\n1. 清單位置由 1 開始計算（第 1 個為位置 1）。\n2. 若最小值出現多次，請輸出最前面出現的那一個位置",examples:[{input:"5\n8 3 5 1 6",output:"4",explanation:"最小值為 1，\n位於第 4 個位置。"},{input:"5\n2 4 2 9 5",output:"1",explanation:"最小值為 2，\n第 1 與第 3 個位置都有，\n取最前面的第 1 個位置。"}],testCases:[{input:"5\n8 3 5 1 6",expectedOutput:"4",score:10},{input:"5\n2 4 2 9 5",expectedOutput:"1",score:10},{input:"5\n7 6 5 4 3",expectedOutput:"5",score:10},{input:"5\n1 9 8 7 6",expectedOutput:"1",score:10},{input:"5\n4 4 4 4 4",expectedOutput:"1",score:10}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/M1-08-SortApplied/seclect-003.sb3"},{id:"seclect-007",code:"M1-08-seclect-007",title:"雙卡同步交換",description:"在資訊課中，老師準備了兩排卡片，\n第一排是學生姓名，第二排是對應的分數。\n每一個位置上的姓名與分數是一組資料，必須一起行動。\n老師指定兩個位置，小華需要把這兩個位置上的資料進行交換。\n交換時，姓名與分數都必須一起交換，其他位置保持不變。\n請你寫一個程式，完成指定位置的「連動清單交換」任務",examples:[{input:"Amy Bob Carl Dora Eric\n80 90 70 85 60\n2 4",output:"Amy Dora Carl Bob Eric\n80 85 70 90 60",explanation:"第2與第4個位置交換，\n姓名與分數必須一起交換。"},{input:"Tom May John Lily Ken\n75 88 92 60 85\n1 5",output:"Ken May John Lily Tom\n85 88 92 60 75",explanation:"第1與第5個位置交換，\n兩個清單同步變動。"}],testCases:[{input:"5\nAmy Bob Carl Dora Eric\n5\n80 90 70 85 60\n2\n2 4",expectedOutput:"Amy Dora Carl Bob Eric 80 85 70 90 60",score:10},{input:"5\nTom May John Lily Ken\n5\n75 88 92 60 85\n2\n1 5",expectedOutput:"Ken May John Lily Tom 85 88 92 60 75",score:10},{input:"5\nA B C D E\n5\n10 20 30 40 50\n2\n3 3",expectedOutput:"A B C D E 10 20 30 40 50",score:10},{input:"5\nAnn Ben Ann Dan Eva\n5\n90 80 90 70 60\n2\n1 3",expectedOutput:"Ann Ben Ann Dan Eva 90 80 90 70 60",score:10},{input:"5\nOne Two Three Four Five\n5\n5 4 3 2 1\n2\n4 5",expectedOutput:"One Two Three Five Four 5 4 3 1 2",score:10}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/M1-08-SortApplied/seclect-007.sb3"},{id:"seclect-008",code:"M1-08-seclect-008",title:"找出最高分與最低分學生的位置與姓名",description:"在整理成績資料時，小華發現每位學生的姓名與分數\n是分別存放在兩個清單中，但相同位置代表同一位學生。\n現在老師希望小華一次找出：\n最高分所在的位置與姓名\n最低分所在的位置與姓名\n以便後續進行成績分析與排序。\n請你寫一個程式，從分數清單中找出最高分與最低分，\n並輸出它們所在的位置與對應的學生姓名。\n注意事項：\n1. 清單位置由 1 開始計算。\n2. 若最高分或最低分出現多次，請輸出最前面出現的那一筆資料",examples:[{input:"Amy Bob Carl Dora Eric\n80 90 70 85 60",output:"2 Bob 5 Eric",explanation:"最高分為 90，在第 2 個位置（Bob）；\n最低分為 60，在第 5 個位置（Eric）。"},{input:"Tom May John Lily Ken\n88 92 92 75 60",output:"2 May 5 Ken",explanation:"最高分為 92，第 2、3 個位置都有，\n取最前面的 May；\n最低分為 60，在第 5 個位置 Ken。"}],testCases:[{input:"Amy Bob Carl Dora Eric\n80 90 70 85 60",expectedOutput:"2 Bob 5 Eric",score:10},{input:"Tom May John Lily Ken\n88 92 92 75 60",expectedOutput:"2 May 5 Ken",score:10},{input:"A B C D E\n10 20 30 40 50",expectedOutput:"5 E 1 A",score:10},{input:"Ann Ben Ann Dan Eva\n90 80 90 70 60",expectedOutput:"1 Ann 5 Eva",score:10},{input:"One Two Three Four Five\n100 90 80 70 60",expectedOutput:"1 One 5 Five",score:10}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/M1-08-SortApplied/seclect-008.sb3"},{id:"seclect-009",code:"M1-08-seclect-009",title:"連動選擇排序第一回合",description:"小華已經學會如何在成績清單中找出最高分與最低分的位置，\n現在老師要他進一步練習連動清單的排序操作。\n桌上有兩個清單：\n學生姓名清單\n對應的分數清單\n相同位置代表同一位學生。\n請你完成選擇排序的第一回合：\n從所有學生中找出分數最高的學生，\n並將這位學生與第 1 個位置的資料進行交換。\n交換時，姓名與分數必須一起交換，\n其餘位置的順序保持不變。\n注意事項：\n1. 只進行第一回合，不需完成整個排序。\n2. 若最高分出現多次，請選擇最前面出現的那一筆資料",examples:[{input:"Amy Bob Carl Dora Eric\n80 90 70 85 60",output:"Bob Amy Carl Dora Eric\n90 80 70 85 60",explanation:"最高分為 90（Bob），\n與第 1 個位置的 Amy 交換。"},{input:"Tom May John Lily Ken\n95 88 92 75 60",output:"Tom May John Lily Ken\n95 88 92 75 60",explanation:"最高分已在第 1 個位置，\n不需交換。"}],testCases:[{input:"Amy Bob Carl Dora Eric\n80 90 70 85 60",expectedOutput:"Bob Amy Carl Dora Eric 90 80 70 85 60",score:10},{input:"Tom May John Lily Ken\n95 88 92 75 60",expectedOutput:"Tom May John Lily Ken 95 88 92 75 60",score:10},{input:"A B C D E\n10 50 30 40 20",expectedOutput:"B A C D E 50 10 30 40 20",score:10},{input:"Ann Ben Ann Dan Eva\n90 80 90 70 60",expectedOutput:"Ann Ben Ann Dan Eva 90 80 90 70 60",score:10},{input:"One Two Three Four Five\n20 100 80 60 40",expectedOutput:"Two One Three Four Five 100 20 80 60 40",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-08-SortApplied/seclect-009.sb3"},{id:"seclect-010",code:"M1-08-seclect-010",title:"完整雙清單排序",description:"小華已經完成「連動選擇排序第一回合」的練習，\n現在老師希望他能夠完成完整的連動排序任務。\n桌上有兩個清單：\n學生姓名清單\n對應的分數清單\n相同位置代表同一位學生。\n請你使用選擇排序法，依照分數由高到低的順序，\n將所有學生進行排序。\n排序時必須注意：\n比較時只比較「分數」\n交換時「姓名與分數必須一起交換」\n不可使用任何排序相關的積木或指令。\n注意事項：\n1. 若分數相同，學生的相對順序不限。\n2. 必須完成整個排序流程",examples:[{input:"Amy Bob Carl Dora Eric\n80 90 70 85 60",output:"Bob Dora Amy Carl Eric\n90 85 80 70 60",explanation:"依分數由高到低排序，\n姓名與分數同步調整。"},{input:"Tom May John Lily Ken\n95 88 92 75 60",output:"Tom John May Lily Ken\n95 92 88 75 60",explanation:"完成所有回合後，\n清單排序完成。"}],testCases:[{input:"Amy Bob Carl Dora Eric\n80 90 70 85 60",expectedOutput:"Bob Dora Amy Carl Eric 90 85 80 70 60",score:10},{input:"Tom May John Lily Ken\n95 88 92 75 60",expectedOutput:"Tom John May Lily Ken 95 92 88 75 60",score:10},{input:"A B C D E\n10 50 30 40 20",expectedOutput:"B D C E A 50 40 30 20 10",score:10},{input:"Ann Ben Ann Dan Eva\n90 80 90 70 60",expectedOutput:"Ann Ann Ben Dan Eva 90 90 80 70 60",score:10},{input:"One Two Three Four Five\n20 100 80 60 40",expectedOutput:"Two Three Four Five One 100 80 60 40 20",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-08-SortApplied/seclect-010.sb3"},{id:"seclect-011",code:"M1-08-seclect-011",title:"排序結果應用-成績排行榜",description:"小華已經完成「完整雙清單排序」，並且將學生依照分數由高到低\n排序完成。\n現在老師希望小華能夠應用排序後的結果，\n製作一份簡單的成績排行榜。\n請你寫一個程式，完成以下任務：\n先依照分數由高到低排序學生資料\n再依排序後的結果，輸出每位學生的名次、姓名與分數\n相同位置的姓名與分數必須保持連動。\n注意事項：\n1. 名次從 1 開始編號。\n2. 若分數相同，名次仍依排序後的順序編號即可。\n3. 不可使用任何排序相關的積木或指令",examples:[{input:"Amy Bob Carl Dora Eric\n80 90 70 85 60",output:"1 Bob 90\n2 Dora 85\n3 Amy 80\n4 Carl 70\n5 Eric 60",explanation:"先完成排序，\n再依序輸出排行榜。"},{input:"Tom May John Lily Ken\n95 88 92 75 60",output:"1 Tom 95\n2 John 92\n3 May 88\n4 Lily 75\n5 Ken 60",explanation:"名次依排序後的位置決定。"}],testCases:[{input:"Amy Bob Carl Dora Eric\n80 90 70 85 60",expectedOutput:"1 Bob 90 2 Dora 85 3 Amy 80 4 Carl 70 5 Eric 60",score:10},{input:"Tom May John Lily Ken\n95 88 92 75 60",expectedOutput:"1 Tom 95 2 John 92 3 May 88 4 Lily 75 5 Ken 60",score:10},{input:"A B C D E\n10 50 30 40 20",expectedOutput:"1 B 50 2 D 40 3 C 30 4 E 20 5 A 10",score:10},{input:"Ann Ben Ann Dan Eva\n90 80 90 70 60",expectedOutput:"1 Ann 90 2 Ann 90 3 Ben 80 4 Dan 70 5 Eva 60",score:10},{input:"One Two Three Four Five\n20 100 80 60 40",expectedOutput:"1 Two 100 2 Three 80 3 Four 60 4 Five 40 5 One 20",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-08-SortApplied/seclect-011.sb3"},{id:"seclect-012",code:"M1-08-seclect-012",title:"多清單整合實戰-學生資料分析",description:"在校務系統中，學生的資料常常分散存放在多個清單中。\n小華目前有三個清單，分別記錄：\n學生姓名清單\n國文成績清單\n數學成績清單\n相同位置代表同一位學生。\n老師希望小華能設計一個程式，將這些資料整合分析，\n完成以下任務：\n計算每位學生的「總分」\n依照總分由高到低排序所有學生\n輸出排序後的學生姓名與總分\n所有清單在排序過程中必須保持位置連動。\n注意事項：\n1. 總分 = 國文成績 + 數學成績。\n2. 若總分相同，依原本出現的先後順序排列。\n3. 不可使用內建排序功能。\n4. 總分不會有同分情形",examples:[{input:"Amy Bob Carl Dora Eric\n80 90 70 85 60\n70 85 80 75 65",output:"Bob 175\nDora 160\nAmy 150\nCarl 150\nEric 125",explanation:"先計算總分，\n再依總分排序。"}],testCases:[{input:"Amy Bob Carl Dora Eric\n80 90 70 85 60\n70 85 75 75 65",expectedOutput:"Bob 175 Dora 160 Amy 150 Carl 145 Eric 125",score:10},{input:"Tom May John Lily Ken\n90 80 85 70 60\n88 90 80 75 65",expectedOutput:"Tom 178 May 170 John 165 Lily 145 Ken 125",score:10},{input:"A B C D E\n80 60 60 50 65\n90 80 70 30 45",expectedOutput:"A 170 B 140 C 130 E 110 D 80",score:10},{input:"Ann Ben Cat Dee Eve\n95 90 85 70 60\n0 10 20 45 25",expectedOutput:"Dee 115 Cat 105 Ben 100 Ann 95 Eve 85",score:10},{input:"One Two Three Four Five\n30 50 70 90 10\n20 40 60 80 100",expectedOutput:"Four 170 Three 130 Five 110 Two 90 One 50",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-08-SortApplied/seclect-012.sb3"}]}}}]);